public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType genericPT = (ParameterizedType) genericType;
    Class<?> raw = (Class<?>) genericPT.getRawType();
    ParameterizedType targetPT = findParameterizedType(targetType, raw);
    if (targetPT == null) {
        return null;
    }
    Type[] args = targetPT.getActualTypeArguments();
    Class<?>[] result = new Class<?>[args.length];
    for (int i = 0; i < args.length; i++) {
        if (args[i] instanceof Class<?>) {
            result[i] = (Class<?>) args[i];
        } else {
            // Cannot resolve type variable or wildcard
            return null;
        }
    }
    return result;
}

private static ParameterizedType findParameterizedType(Class<?> target, Class<?> raw) {
    // Check interfaces
    for (Type iface : target.getGenericInterfaces()) {
        ParameterizedType pt = getParameterizedType(iface, raw);
        if (pt != null) {
            return pt;
        }
    }
    // Check superclass
    Type superType = target.getGenericSuperclass();
    if (superType != null) {
        ParameterizedType pt = getParameterizedType(superType, raw);
        if (pt != null) {
            return pt;
        }
    }
    return null;
}

private static ParameterizedType getParameterizedType(Type type, Class<?> raw) {
    if (type instanceof ParameterizedType) {
        ParameterizedType pt = (ParameterizedType) type;
        if (pt.getRawType() == raw) {
            return pt;
        }
        // Search in the raw type's hierarchy
        Class<?> rawClass = (Class<?>) pt.getRawType();
        return findParameterizedType(rawClass, raw);
    } else if (type instanceof Class<?>) {
        Class<?> clazz = (Class<?>) type;
        if (clazz == raw) {
            return null;
        }
        return findParameterizedType(clazz, raw);
    }
    return null;
}

