public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new NullPointerException("String is null");
    }
    if (index < 0 || len < 0 || index + len > str.length()) {
        throw new IndexOutOfBoundsException("Invalid index or length");
    }
    int end = index + len;
    int size = 0;
    for (int i = index; i < end; i++) {
        char c = str.charAt(i);
        if (c <= 0x7F) {
            size += 1;
        } else if (c <= 0x7FF) {
            size += 2;
        } else if (c >= 0xD800 && c <= 0xDBFF) { // high surrogate
            if (i + 1 < end) {
                char d = str.charAt(i + 1);
                if (d >= 0xDC00 && d <= 0xDFFF) { // low surrogate
                    size += 4;
                    i++; // skip low surrogate
                    continue;
                }
            }
            // invalid surrogate or no following low surrogate
            size += 3;
        } else if (c >= 0xDC00 && c <= 0xDFFF) { // low surrogate without preceding high surrogate
            size += 3;
        } else {
            size += 3;
        }
    }
    return size;
}

