    if (str == null && suffix == null) {
        return true;
    }
    if (str == null || suffix == null) {
        return false;
    }
    int strLen = str.length();
    int suffixLen = suffix.length();
    if (suffixLen > strLen) {
        return false;
    }
    int start = strLen - suffixLen;
    return str.regionMatches(ignoreCase, start, suffix, 0, suffixLen);
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    String rawPath = u.getRawPath();
    java.util.List<PathSegmentImpl> segments = new java.util.ArrayList<>();
    if (rawPath == null || rawPath.isEmpty()) {
        return segments;
    }
    // If the path is absolute, ignore the leading '/'
    if (rawPath.startsWith("/")) {
        rawPath = rawPath.substring(1);
    }
    if (rawPath.isEmpty()) {
        return segments;
    }
    String[] parts = rawPath.split("/", -1);
    for (String part : parts) {
        String decoded;
        if (decode) {
            try {
                decoded = java.net.URLDecoder.decode(part, java.nio.charset.StandardCharsets.UTF_8.name());
            } catch (IllegalArgumentException e) {
                throw new IllegalArgumentException("Invalid percent-encoding in path segment: " + part, e);
            }
        } else {
            decoded = part;
        }
        segments.add(new PathSegmentImpl(part, decoded));
    }
    return segments;
}

