@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    // Ensure the target type is Character or char
    if (type != Character.class && type != char.class) {
        throw new IllegalArgumentException("Target type must be java.lang.Character or char");
    }

    if (value == null) {
        return null;
    }

    // If already a Character, return as is
    if (value instanceof Character) {
        return value;
    }

    // If it's a String, it must be a single character
    if (value instanceof String) {
        String str = (String) value;
        if (str.length() == 1) {
            return str.charAt(0);
        } else {
            throw new IllegalArgumentException("Cannot convert String to Character: length != 1");
        }
    }

    // If it's a Number, cast to int and then to char
    if (value instanceof Number) {
        int intVal = ((Number) value).intValue();
        if (intVal >= Character.MIN_VALUE && intVal <= Character.MAX_VALUE) {
            return (char) intVal;
        } else {
            throw new IllegalArgumentException("Number value out of char range");
        }
    }

    // For any other type, attempt to use its string representation
    String str = value.toString();
    if (str.length() == 1) {
        return str.charAt(0);
    } else {
        throw new IllegalArgumentException("Cannot convert value to Character: toString length != 1");
    }
}

