            if (!created) {
                throw new java.io.IOException("Unable to create distribution directory: " + distPath);
            }
        }
        // Load configuration properties from config.properties in dist directory
        java.io.File configFile = new java.io.File(distDir, "config.properties");
        if (configFile.exists()) {
            java.util.Properties props = new java.util.Properties();
            try (java.io.FileInputStream fis = new java.io.FileInputStream(configFile)) {
