private static int digitValue(final char c) {
    // ASCII digits 0-9
    if (c >= '0' && c <= '9') {
        return c - '0';
    }
    // ASCII uppercase letters A-Z
    if (c >= 'A' && c <= 'Z') {
        return c - 'A' + 10;
    }
    // ASCII lowercase letters a-z
    if (c >= 'a' && c <= 'z') {
        return c - 'a' + 10;
    }
    // Non-ASCII or unsupported character
    return -1;
}

private Map<String,Object> buildContent(JsonObject jsonObject){
    Map<String,Object> content = new HashMap<>();
    if(jsonObject == null){
        return content;
    }
    for(Map.Entry<String, JsonElement> entry : jsonObject.entrySet()){
        String key = entry.getKey();
        JsonElement value = entry.getValue();
        if(value != null){
            if(value.isJsonPrimitive()){
                JsonPrimitive prim = value.getAsJsonPrimitive();
                if(prim.isString()){
                    content.put(key, prim.getAsString());
                } else if(prim.isNumber()){
                    content.put(key, prim.getAsNumber());
                } else if(prim.isBoolean()){
                    content.put(key, prim.getAsBoolean());
                } else {
                    content.put(key, prim.getAsString());
                }
            } else if(value.isJsonObject()){
                content.put(key, value.getAsJsonObject());
            } else if(value.isJsonArray()){
                content.put(key, value.getAsJsonArray());
            } else if(value.isJsonNull()){
                content.put(key, null);
            } else {
                content.put(key, value.toString());
            }
        } else {
            content.put(key, null);
        }
    }
    return content;
}

