final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer){
    if (constantPoolEntryIndex < 1) {
        throw new IllegalArgumentException("Constant pool index must be >= 1");
    }
    int offset = 10; // constant pool starts after magic(4) + minor(2) + major(2) + constant_pool_count(2)
    for (int i = 1; i < constantPoolEntryIndex; i++) {
        int tag = classFileBuffer[offset] & 0xFF;
        offset++;
        switch (tag) {
            case 1: // CONSTANT_Utf8
                int len = ((classFileBuffer[offset] & 0xFF) << 8) | (classFileBuffer[offset + 1] & 0xFF);
                offset += 2 + len;
                break;
            case 3: // CONSTANT_Integer
            case 4: // CONSTANT_Float
                offset += 4;
                break;
            case 5: // CONSTANT_Long
            case 6: // CONSTANT_Double
                offset += 8;
                i++; // these take up two entries
                break;
            case 7: // CONSTANT_Class
            case 8: // CONSTANT_String
            case 9: // CONSTANT_Fieldref
            case 10: // CONSTANT_Methodref
            case 11: // CONSTANT_InterfaceMethodref
            case 12: // CONSTANT_NameAndType
            case 18: // CONSTANT_InvokeDynamic
                offset += 4;
                break;
            case 15: // CONSTANT_MethodHandle
                offset += 3;
                break;
            case 16: // CONSTANT_MethodType
                offset += 2;
                break;
            default:
                throw new IllegalArgumentException("Unknown constant pool tag: " + tag);
        }
    }
    int tag = classFileBuffer[offset] & 0xFF;
    if (tag != 1) {
        throw new IllegalArgumentException("Expected CONSTANT_Utf8 at index " + constantPoolEntryIndex);
    }
    offset++;
    int len = ((classFileBuffer[offset] & 0xFF) << 8) | (classFileBuffer[offset + 1] & 0xFF);
    offset += 2;
    String s = new String(classFileBuffer, offset, len, java.nio.charset.StandardCharsets.UTF_8);
    s.getChars(0, len, charBuffer, 0);
    return s;
}

private static char decodeHexNibble(final char c){
    if (c >= '0' && c <= '9') {
        return (char)(c - '0');
    } else if (c >= 'a' && c <= 'f') {
        return (char)(c - 'a' + 10);
    } else if (c >= 'A' && c <= 'F') {
        return (char)(c - 'A' + 10);
    } else {
        return Character.MAX_VALUE;
    }
}

