    }
    return result;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // Create a circulator starting at the given node and direction
    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);
    while (true) {
        Node current = circ.getNode();
        // If the current node satisfies the predicate, return this circulator
        if (predicate.test(current)) {
            return circ;
        }
        // If we have reached the stop node, return the circulator pointing to it
        if (current.equals(stop)) {
            return circ;
        }
        // Move to the next node in the specified direction
        circ = dir > 0 ? circ.next() : circ.prev();
