public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    if (byteLength < 0) {
        throw new IllegalArgumentException("byteLength must be non-negative");
    }
    if (byteArrayValue != null) {
        if (byteOffset < 0 || byteOffset > byteArrayValue.length) {
            throw new IndexOutOfBoundsException("byteOffset out of bounds");
        }
        if (byteOffset + byteLength > byteArrayValue.length) {
            throw new IndexOutOfBoundsException("byteLength extends beyond array");
        }
    }
    int newLen = length + byteLength;
    if (newLen > bytes.length) {
        int newCap = Math.max(bytes.length * 2, newLen);
        byte[] newBytes = new byte[newCap];
        System.arraycopy(bytes, 0, newBytes, 0, length);
        bytes = newBytes;
    }
    if (byteArrayValue == null) {
        for (int i = 0; i < byteLength; i++) {
            bytes[length + i] = 0;
        }
    } else {
        System.arraycopy(byteArrayValue, byteOffset, bytes, length, byteLength);
    }
    length = newLen;
    return this;
}

