protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new NullPointerException("tour and graph must not be null");
    }
    // If the tour is empty, return an empty path
    if (tour.isEmpty()) {
        return new GraphPathImpl<>(graph, new ArrayList<>(), new ArrayList<>(), 0.0);
    }

    // Prepare containers for vertices and edges in order
    List<V> vertexList = new ArrayList<>();
    List<E> edgeList = new ArrayList<>();

    // Copy the set of edges to a mutable set for traversal
    Set<E> remaining = new HashSet<>(tour);

    // Pick an arbitrary starting edge to determine the start vertex
    E firstEdge = remaining.iterator().next();
    V startVertex = graph.getEdgeSource(firstEdge);
    vertexList.add(startVertex);
    V currentVertex = startVertex;

    // Traverse edges to build the path
    while (!remaining.isEmpty()) {
        boolean found = false;
        Iterator<E> it = remaining.iterator();
        while (it.hasNext()) {
            E e = it.next();
            if (graph.getType().isDirected()) {
                if (graph.getEdgeSource(e).equals(currentVertex)) {
                    // Directed edge matches current vertex as source
                    edgeList.add(e);
                    it.remove();
                    currentVertex = graph.getEdgeTarget(e);
                    vertexList.add(currentVertex);
                    found = true;
                    break;
                }
            } else {
                // Undirected graph: edge can be traversed in either direction
                if (graph.getEdgeSource(e).equals(currentVertex)) {
                    edgeList.add(e);
                    it.remove();
                    currentVertex = graph.getEdgeTarget(e);
                    vertexList.add(currentVertex);
                    found = true;
                    break;
                } else if (graph.getEdgeTarget(e).equals(currentVertex)) {
                    edgeList.add(e);
                    it.remove();
                    currentVertex = graph.getEdgeSource(e);
                    vertexList.add(currentVertex);
                    found = true;
                    break;
                }
            }
        }
        if (!found) {
            throw new IllegalArgumentException("The provided edge set does not form a continuous path.");
        }
    }

    // Compute total weight of the path
    double totalWeight = 0.0;
    for (E e : edgeList) {
        totalWeight += graph.getEdgeWeight(e);
    }

    // Return the constructed path
    return new GraphPathImpl<>(graph, vertexList, edgeList, totalWeight);
}

