int addConstantNameAndType(final String name, final String descriptor) {
    // Search for an existing CONSTANT_NameAndType_info with the same name and descriptor
    for (int i = 1; i < constantPool.size(); i++) {
        ConstantPoolInfo info = constantPool.get(i);
        if (info instanceof ConstantNameAndTypeInfo) {
            ConstantNameAndTypeInfo nt = (ConstantNameAndTypeInfo) info;
            String existingName = getUtf8String(nt.nameIndex);
            String existingDescriptor = getUtf8String(nt.descriptorIndex);
            if (name.equals(existingName) && descriptor.equals(existingDescriptor)) {
                return i; // already present
            }
        }
    }

    // Add the name and descriptor as UTF-8 entries if they are not already present
    int nameIndex = addUtf8(name);
    int descriptorIndex = addUtf8(descriptor);

    // Create and add the new NameAndType entry
    ConstantNameAndTypeInfo nt = new ConstantNameAndTypeInfo(nameIndex, descriptorIndex);
    int newIndex = constantPool.size(); // index where the new entry will be placed
    constantPool.add(nt);
    return newIndex;
}

