    }
    ListNodeImpl<E> prev = node.prev;
    ListNodeImpl<E> next = node.next;
    if (prev == null) {
        head = next;
    } else {
        prev.next = next;
    }
    if (next == null) {
        tail = prev;
    } else {
        next.prev = prev;
    }
    node.prev = null;
    node.next = null;
    size--;
    return true;
}

