public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null) {
        return;
    }
    // Clamp indices to valid range
    if (from < 0) {
        from = 0;
    }
    if (to >= arr.length) {
        to = arr.length - 1;
    }
    if (from >= to) {
        return;
    }
    int i = from;
    int j = to;
    while (i < j) {
        V temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
        i++;
        j--;
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    // If the source list is empty or the same as this list, nothing to do
    if (list == null || list.size == 0 || this == list) {
        return;
    }

    // If this list is empty, simply adopt the source list's nodes
    if (this.size == 0) {
        this.head = list.head;
        this.tail = list.tail;
    } else {
        // Link the tail of this list to the head of the source list
        this.tail.next = list.head;
        list.head.prev = this.tail;
        this.tail = list.tail;
    }

    // Update the size of this list
    this.size += list.size;

    // Clear the source list
    list.head = null;
    list.tail = null;
    list.size = 0;
}

private static boolean startsWith(final String str, final String prefix, final boolean ignoreCase) {
    // If both are null, consider it a match
    if (str == null) {
        return prefix == null;
    }
    // If the string is not null but the prefix is null, it's not a match
    if (prefix == null) {
        return false;
    }
    // Use regionMatches for case-insensitive comparison if requested
    if (ignoreCase) {
        return str.regionMatches(true, 0, prefix, 0, prefix.length());
    }
    // Otherwise use the standard startsWith
    return str.startsWith(prefix);
}

