public static Meteor lookup(HttpServletRequest r) {
    if (r == null) {
        return null;
    }

    // 1. Try to get a Meteor instance from the request attributes
    Object attr = r.getAttribute("meteor");
    if (attr instanceof Meteor) {
        return (Meteor) attr;
    }

    // 2. Try to get a Meteor instance from the session attributes
    HttpSession session = r.getSession(false);
    if (session != null) {
        Object sessAttr = session.getAttribute("meteor");
        if (sessAttr instanceof Meteor) {
            return (Meteor) sessAttr;
        }
    }

    // 3. Try to load a Meteor by ID passed as a request parameter
    String idParam = r.getParameter("meteorId");
    if (idParam != null) {
        try {
            long id = Long.parseLong(idParam);
            // Assuming Meteor has a static finder method
            return Meteor.findById(id);
        } catch (NumberFormatException e) {
            // ignore and fall through to return null
        }
    }

    // 4. No Meteor found
    return null;
}

