    java.util.List<Pair<List<Pair<Integer,Integer>>,E>> globalSeparators = new java.util.ArrayList<>();
    for (E e : graph.getEdges()){
        java.util.List<java.util.List<Pair<Integer,Integer>>> separators = computeMinimalSeparators(e);
        for (java.util.List<Pair<Integer,Integer>> sep : separators){
            globalSeparators.add(new Pair<>(sep, e));
        }
    }
    return globalSeparators;
}

