public void abbreviate(final int nameStart, final StringBuffer buf) {
    if (name == null) {
        return;
    }
    String[] parts = name.split("\\s+");
    int start = Math.max(0, nameStart);
    for (int i = 0; i < parts.length; i++) {
        if (i > 0) {
            buf.append(' ');
        }
        if (i >= start) {
            if (!parts[i].isEmpty()) {
                buf.append(parts[i].charAt(0)).append('.');
            }
        } else {
            buf.append(parts[i]);
        }
    }
}

public static Type resolveBound(TypeVariable<?> typeVariable) {
    if (typeVariable == null) {
        return Unknown.class;
    }
    Type[] bounds = typeVariable.getBounds();
    if (bounds == null || bounds.length == 0) {
        return Unknown.class;
    }
    Type bound = bounds[0];
    if (bound instanceof Class<?>) {
        return bound;
    }
    if (bound instanceof ParameterizedType) {
        return ((ParameterizedType) bound).getRawType();
    }
    if (bound instanceof TypeVariable<?>) {
        return resolveBound((TypeVariable<?>) bound);
    }
    // For WildcardType, GenericArrayType, or other types, return Unknown
    return Unknown.class;
}

private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    // A set with 0 or 1 vertex is trivially a clique
    if (vertices.size() <= 1) {
        return true;
    }
    // Convert to a list for indexed access
    List<V> vertexList = new ArrayList<>(vertices);
    int n = vertexList.size();
    for (int i = 0; i < n; i++) {
        V v1 = vertexList.get(i);
        for (int j = i + 1; j < n; j++) {
            V v2 = vertexList.get(j);
            // Check if an edge exists between v1 and v2
            if (!graph.containsEdge(v1, v2)) {
                return false;
            }
        }
    }
    return true;
}

private List<Integer> computeLowerBounds(List<K> keys) {
    int n = keys.size();
    List<Integer> result = new ArrayList<>(n);
    for (int i = 0; i < n; i++) {
        result.add(-1);
    }
    Integer[] indices = new Integer[n];
    for (int i = 0; i < n; i++) {
        indices[i] = i;
    }
    Arrays.sort(indices, (i, j) -> ((Comparable) keys.get(i)).compareTo(keys.get(j)));
    K lastKey = null;
    int lastIndex = -1;
    for (int idx : indices) {
        K key = keys.get(idx);
        if (lastKey == null || ((Comparable) key).compareTo(lastKey) > 0) {
            result.set(idx, lastIndex);
            lastKey = key;
            lastIndex = idx;
        } else {
            result.set(idx, lastIndex);
        }
    }
    return result;
}

private void pop(final String descriptor) {
    int i = 0;
    if (descriptor.charAt(0) == '(') {
        i = 1;
        while (descriptor.charAt(i) != ')') {
            // Skip one argument type
            char c = descriptor.charAt(i);
            if (c == '[') {
                // Array type: skip all '['
                while (descriptor.charAt(i) == '[') {
                    i++;
                }
                c = descriptor.charAt(i);
                if (c == 'L') {
                    i++; // skip 'L'
                    while (descriptor.charAt(i) != ';') {
                        i++;
                    }
                    i++; // skip ';'
                } else {
                    // Primitive component type
                    i++;
                }
            } else if (c == 'L') {
                i++; // skip 'L'
                while (descriptor.charAt(i) != ';') {
                    i++;
                }
                i++; // skip ';'
            } else {
                // Primitive type
                i++;
            }
            // Pop the type from the stack
            outputFrameStack.pop();
        }
        // Skip ')'
        i++;
        // Skip return type descriptor (do not pop)
        if (i < descriptor.length()) {
            char c = descriptor.charAt(i);
            if (c == '[') {
                while (descriptor.charAt(i) == '[') {
                    i++;
                }
                c = descriptor.charAt(i);
                if (c == 'L') {
                    i++;
                    while (descriptor.charAt(i) != ';') {
                        i++;
                    }
                    i++;
                } else {
                    i++;
                }
            } else if (c == 'L') {
                i++;
                while (descriptor.charAt(i) != ';') {
                    i++;
                }
                i++;
            } else {
                // Primitive or void
                i++;
            }
        }
    } else {
        // Single type descriptor: pop one type
        outputFrameStack.pop();
    }
}

