public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        return null;
    }
    // Determine if the base path is absolute
    boolean isAbsolute = path.startsWith("/");
    // Determine the base path (drop file name if it looks like a file)
    String basePath = path;
    int lastSlash = path.lastIndexOf('/');
    if (lastSlash != -1) {
        // If there is a dot after the last slash, treat as file and drop it
        if (path.indexOf('.', lastSlash + 1) != -1) {
            basePath = path.substring(0, lastSlash);
        }
    } else {
        // No slash: treat entire path as file name
        if (path.indexOf('.') != -1) {
            basePath = "";
        }
    }
    // Split base path into components
    java.util.List<String> stack = new java.util.ArrayList<>();
    if (!basePath.isEmpty()) {
        String[] baseParts = basePath.split("/");
        for (String part : baseParts) {
            if (part.isEmpty() || part.equals(".")) {
                continue;
            }
            if (part.equals("..")) {
                if (!stack.isEmpty()) {
                    stack.remove(stack.size() - 1);
                } else if (!isAbsolute) {
                    stack.add("..");
                }
            } else {
                stack.add(part);
            }
        }
    }
    // Split relative path into components and apply
    String[] relParts = relativePath.split("/");
    for (String part : relParts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.remove(stack.size() - 1);
            } else if (!isAbsolute) {
                stack.add("..");
            }
        } else {
            stack.add(part);
        }
    }
    // Build the resulting path
    StringBuilder result = new StringBuilder();
    if (isAbsolute) {
        result.append("/");
    }
    for (int i = 0; i < stack.size(); i++) {
        if (i > 0) {
            result.append("/");
        }
        result.append(stack.get(i));
    }
    // If result is empty and absolute, return "/"
    if (result.length() == 0 && isAbsolute) {
        return "/";
    }
    return result.toString();
}

