public static int indexOfExtension(String filename) {
    if (filename == null) {
        return -1;
    }
    int dotIndex = filename.lastIndexOf('.');
    if (dotIndex == -1) {
        return -1;
    }
    int lastUnixSep = filename.lastIndexOf('/');
    int lastWindowsSep = filename.lastIndexOf('\\');
    int sepIndex = Math.max(lastUnixSep, lastWindowsSep);
    if (sepIndex > dotIndex) {
        return -1;
    }
    if (dotIndex == filename.length() - 1) {
        return -1;
    }
    return dotIndex;
}

