public static boolean substringMatch(CharSequence str, int index, CharSequence substring) {
    if (str == null || substring == null) {
        throw new NullPointerException("String arguments cannot be null");
    }
    int strLen = str.length();
    int subLen = substring.length();

    // Empty substring always matches at any valid index
    if (subLen == 0) {
        return index >= 0 && index <= strLen;
    }

    // Check bounds
    if (index < 0 || index > strLen - subLen) {
        return false;
    }

    for (int i = 0; i < subLen; i++) {
        if (str.charAt(index + i) != substring.charAt(i)) {
            return false;
        }
    }
    return true;
}

protected void append(LoggingEvent event) {
    String message = event.getRenderedMessage();
    // Iterate over all connected clients and send the log message
    for (java.net.Socket client : clients) {
        try {
            java.io.PrintWriter out = new java.io.PrintWriter(client.getOutputStream(), true);
            out.println(message);
        } catch (java.io.IOException e) {
            // If an error handler is available, report the error
            if (errorHandler != null) {
                errorHandler.error("Failed to send log message to client", e, 0);
            }
        }
    }
}

