public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    java.util.List<ThreadSnapshot> result = new java.util.ArrayList<>();
    if (file == null || !file.exists() || !file.isFile()) {
        return result;
    }
    if (timeRanges == null || timeRanges.isEmpty()) {
        return result;
    }
    com.fasterxml.jackson.databind.ObjectMapper mapper = new com.fasterxml.jackson.databind.ObjectMapper();
    java.nio.file.Path path = file.toPath();
    java.util.stream.Stream<String> lines = java.nio.file.Files.lines(path);
    try {
        lines.forEach(line -> {
            if (line == null || line.trim().isEmpty()) {
                return;
            }
            try {
                ThreadSnapshot snapshot = mapper.readValue(line, ThreadSnapshot.class);
                long ts = snapshot.getTimestamp();
                for (ProfileAnalyzeTimeRange range : timeRanges) {
                    if (ts >= range.getStartTime() && ts <= range.getEndTime()) {
                        result.add(snapshot);
                        break;
                    }
                }
            } catch (Exception e) {
                // ignore malformed lines
            }
        });
    } finally {
        lines.close();
    }
    return result;
}
